--
-- Table structure for table `cms_template_list`
--

DROP TABLE IF EXISTS `cms_template_list`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cms_template_list` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `createdAt` datetime DEFAULT NULL COMMENT '创建时间',
  `updatedAt` datetime DEFAULT NULL COMMENT '更新时间',
  `template_uuid` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '模板UUID',
  `title` varchar(255) DEFAULT NULL COMMENT '模板名称',
  `type` varchar(255) DEFAULT 'index' COMMENT '类型',
  `name` varchar(255) DEFAULT NULL COMMENT '文件名称',
  `html` text COMMENT '文件内容',
  `isd` tinyint(1) DEFAULT '0' COMMENT '是否默认',
  `isu` tinyint(1) DEFAULT '0' COMMENT '使用中',
  `uuid` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'UUID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `cms_template_list_uuid` (`uuid`),
  KEY `cms_template_list_template_uuid` (`template_uuid`)
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

