CREATE TABLE `mc_member` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `createdAt` datetime DEFAULT NULL COMMENT '创建时间',
  `updatedAt` datetime DEFAULT NULL COMMENT '更新时间',
  `username` varchar(255) DEFAULT NULL COMMENT '用户名',
