/*!40000 ALTER TABLE `sys_project_ready` DISABLE KEYS */;
INSERT INTO `sys_project_ready` VALUES ('2025-08-24 22:14:16',2,'2025-08-27 17:09:32','permit','无','无','无','可以提前联系四大工种：水电工、泥工、木工、油漆工','1、办理好装修许可证（提前联系物业，询问办理装修许可证所需的手续）；\n2、开通水电，水电各充值200元；\n3、根据房间规划提前联系相应商家：中央空调、地暖、新风系统、全屋智能系统（家具、家电、定制柜体等商家能提前联系到，水电定位时能到场一起沟通最好）等；\n4、验房；'),('2025-08-27 17:11:45',3,'2025-08-27 17:11:45','temporary_utilities','无','扫把、铲子、临时便盆','无','开工前，再次与水电工、泥工及相关商家确认好时间；','让物业通水、通电，确保水电表里有钱'),('2025-08-27 17:15:29',4,'2025-08-27 17:15:29','utility_positioning','无','闸阀、临时水龙头、空开、插线板、一点水管和电线，可提前与水电工沟通具体数量，开工当天需要使用；','当地、当天都能买齐，建议提前一天送到','水电工、泥工及相关商家','泥瓦工先弹出全屋水平线，水电工定位需根据水平线的高度来确定点位，管道过不了的需要标出来，打拆时该打的就要打'),('2025-08-27 17:17:10',5,'2025-08-27 17:17:10','safety_protection','无','木方、钢钉或者钢丝网及其它','提前联系商家、当时当地应有现货','自己弄或者让木工师傅做','1、需要拆的窗户也一并拆除；\n2、全屋要烧防盗网的可以在建渣清理后烧防盗网，此时就可以不做保护；'),('2025-08-27 17:17:48',6,'2025-08-27 17:17:48','demolition','无','无','无','提前联系好打拆师傅','需要拆的窗户也一并拆除'),('2025-08-27 17:18:38',7,'2025-08-27 17:18:38','debris_removal','无','沙、水泥、火砖等','无','提前联系好清建渣的师傅','1、建渣清完后，如果需要先砌墙，就需要泥工师傅计算材料，建渣清理后就及时送到工地；\n2、如果建渣清理完后就做水电，就需先送2车沙、1包水泥及水电材料；'),('2025-08-27 17:19:32',8,'2025-08-27 17:19:32','new_wall','无','沙、水泥、火砖等，具体数量由泥工师傅给出','当地应有现货','提前联系泥工师傅，约好施工时间，让其给出材料种类、数量；','无'),('2025-08-27 17:20:24',9,'2025-08-27 17:20:24','security_net','防盗网需提前2-3天联系商家量尺、准备材料','无','2-3天','商家自行联系','无'),('2025-08-27 17:20:53',10,'2025-08-27 17:20:53','grooving','无','无','无','新建完墙体、干燥后，需要补开线槽的，提前联系打拆师傅','无'),('2025-08-27 17:21:28',11,'2025-08-27 17:21:28','drilling','无','无','无','可询问水电工什么时间钻孔比较合适，一般水电工进场前或进场当天钻孔比较合适','无'),('2025-08-27 17:22:18',12,'2025-08-27 17:22:18','hydropower_labor','水电材料，具体种类、数量由水电工给出','无','当地应该有现货，需提前一天送货到场，并验收','提前联系水电工，并让其给出材料清单','无'),('2025-08-27 17:23:33',13,'2025-08-27 17:23:33','hydropower_test','无','无','无','水电完工前，提前联系商家试压，具体时间可询问水电工','水电全部完工后再试压、拍全屋水电线路铺排视频'),('2025-08-27 17:24:43',14,'2025-08-27 17:24:43','gas_pipe','无','无','无','每个地方的规定可能有所差别，水电开始施工前可到燃气公司咨询，水电完工后铺燃气管道，需要准备什么资料，铺管道的时候联系谁，后面通气需要什么流程可一并咨询；','铺燃气管道的时候可以问一下师傅后面通气的条件，以免装修好后通不了气；'),('2025-08-27 17:26:44',15,'2025-08-27 17:26:44','central_ac','水电即将完工前，联系相应商家，让其备货，验收合格后再安装','无','3-5天','由商家安排','预计水电完工时间，提前3-5天联系商家备货；'),('2025-08-27 17:27:55',16,'2025-08-27 17:27:55','floor_heating','水电完工前，联系相应商家，让其备货，验收合格后再安装','无','当地应该有现货，但须提前联系商家备货','由商家安排','无'),('2025-08-27 17:30:19',17,'2025-08-27 17:30:19','leveling','无','水电完工后（有地暖的需在地暖完工后），按照泥工的清单要求进行辅材的准备；','当地应该有现货，但须提前联系商家送货','提前联系泥工，让其安排好施工时间','无'),('2025-08-27 17:31:25',18,'2025-08-27 17:31:25','waterproofing_1st','防水、强固，数量由师傅给出','品类、数量由师傅给出','当地应该有现货，但须提前联系商家送货','提前联系师傅，商家包了的防水，直接联系商家即可','厨卫干透后方可进行防水施工'),('2025-08-27 17:32:25',19,'2025-08-27 17:32:25','bathroom_fill','根据回填方式的不同、联系不同的商家或师傅，由其给出数量','品类、数量由师傅给出','当地应该有现货，但须提前联系商家送货','提前联系相应的师傅，商家包了的，直接联系商家即可','卫生间回填主要有建渣回填，轻质回填（发泡回填），架空回填'),('2025-08-27 17:33:15',20,'2025-08-27 17:33:15','leveling_2nd','无','回填彻底干燥后，按照泥工的清单要求进行辅材的准备（沙、水泥等）；','当地应该有现货，但须提前联系商家送货','提前联系泥工，让其安排好施工时间','无'),('2025-08-27 17:34:19',21,'2025-08-27 17:34:19','waterproofing_2nd','防水材料数量由师傅给出','品类、数量由师傅给出','当地应该有现货，但须提前联系商家送货','提前联系师傅，商家包了的防水，直接联系商家即可','二次找平干透后方可进行防水施工'),('2025-08-27 17:35:25',22,'2025-08-27 17:35:25','roughen','拉毛材料品类、数量由师傅给出','品类、数量由师傅给出','当地应该有现货，但须提前联系商家送货','提前联系师傅，如果防水商家包含了的，直接联系商家即可','防水干透后才能拉毛'),('2025-08-27 17:36:05',23,'2025-08-27 17:36:05','wood_ceiling','木工给出吊顶材料的品类、数量','木工给出吊顶材料的品类、数量','当地应该有现货，但须提前联系商家送货','提前联系师傅，约好具体施工日期','吊顶的区域、造型事先沟通好'),('2025-08-27 17:36:37',24,'2025-08-27 17:36:37','water_test','无','无','无','无','带上钳子，先关总闸，再打开厨卫的堵头，一个区域一个区域的开，时刻关注水量，不要溢出来。'),('2025-08-27 17:37:31',25,'2025-08-27 17:37:31','window_frame','窗户提前由商家量尺，业主确认下单','无','根据各商家的具体情况一般5-10天','有商家自行联系，只需告诉商家具体的安装时间','窗户大小能确定后，即可让商家测量出窗户结构图，及时下单生产'),('2025-08-27 17:38:29',26,'2025-08-27 17:38:29','mason_work','墙地砖提前与商家确定样式、规格，问清备货周期，防水结束后即可施工，数量由商家计算','泥工给出品类、数量（沙、水泥、背胶、瓷砖胶、隔音棉、扎带等）','根据各商家的具体情况一般5-10天','提前联系泥工，沟通好具体施工时间','无'),('2025-08-27 17:39:10',27,'2025-08-27 17:39:10','stove_sink','灶台石、菜盆','砖夹灶需要沙、水泥，成品地柜由石材商家准备辅材','根据各商家的具体情况一般3-5天','由石材商家自行联系工人','提前选好灶台石和菜盆'),('2025-08-27 17:39:59',28,'2025-08-27 17:39:59','entrance_door','入户门','所需辅材一般由商家准备','根据各商家的具体情况一般3-5天','由商家自行联系安装工人','提前选好入户门样式'),('2025-08-27 17:40:41',29,'2025-08-27 17:40:41','safe_window_frame','窗户提前由商家量尺，业主确认下单','无','根据各商家的具体情况一般5-10天','有商家自行联系，只需告诉商家具体的安装时间','窗户大小能确定后，即可让商家测量出窗户结构图，及时下单生产'),('2025-08-27 17:42:26',30,'2025-08-27 17:42:26','grout','美缝材料','无','根据各商家的具体情况一般3-5天，大部分当地均有现货','可以自己购买美缝材料，找师傅做，也可以包给师傅做，贴砖完成2天后就可让师傅现场配色','墙地砖干透后才能美缝'),('2025-08-27 17:43:23',31,'2025-08-27 17:43:23','floor_protection','地保材料','胶带、美工刀','网上购买一般需要3-5天，当地一般都有现货','可以自己贴，也可以让保洁贴','有柜体的地方无需保护'),('2025-08-27 17:44:24',32,'2025-08-27 17:44:24','gypsum_first','具体品类、数量清单由油漆师傅给出','无','网上购买一般需要3-5天，当地一般都有现货，不建议网上购买，有问题售后很麻烦','地膜铺好后即可送货、开始施工，提前联系师傅、沟通好具体施工时间','无'),('2025-08-27 17:45:21',33,'2025-08-27 17:45:21','wardrobe_install','定制商家自行测量、设计、备货，现场打柜子就由师傅给出材料的品类、数量清单；','无','定制生产周期一般20天左右，打柜子当地一般有现货','定制由商家安排工人，打柜子需自行联系工人','定制在吊顶后就可量尺设计，打柜子需在贴砖后一般与吊顶同步由相同的师傅施工；'),('2025-08-27 17:46:49',34,'2025-08-27 17:46:49','range_hood_heater','烟机灶、热水器','止逆阀可自行准备，让师傅安装','网购一般3-5天，当地购买，应该有现货','电器类产品一般都含安装，师傅由商家安排','定制在吊顶后就可量尺设计，打柜子需在贴砖后一般与吊顶同步由相同的师傅施工；'),('2025-08-27 17:48:08',35,'2025-08-27 17:48:08','window_glass','玻璃','商家自备','备货周期一般5-10天','提前与商家沟通好玻璃安装时间','定制（衣柜、鞋柜等）安装前可安装玻璃，防止雨水打湿柜体和墙面'),('2025-08-27 17:49:12',36,'2025-08-27 17:49:12','kitchen_bath_door','厨卫门、隔断','商家自备','备货周期一般5-10天','一般由商家负责，提前与商家沟通好安装时间','墙地砖完工即可量尺、选品备货'),('2025-08-27 17:49:56',37,'2025-08-27 17:49:56','bedroom_door','卧室门','商家自备','备货周期一般10-15天','一般由商家负责，提前与商家沟通好安装时间','墙地砖完工即可量尺、选品备货，卧室门一般高于卫生间门'),('2025-08-27 17:50:38',38,'2025-08-27 17:50:38','gypsum_line','石膏线条','商家/工人自备','网购一般3-5天，当地一般有现货','可直接与安装工或商家联系','定制（柜体）安装好后即可安装石膏线条'),('2025-08-27 17:51:13',39,'2025-08-27 17:51:13','bay_window_stone','石材','沙、水泥等','量尺、制作一般需要2-3天','商家自行联系','提前确定好样式、颜色，飘窗石可同步与灶台石一起安装'),('2025-08-27 17:51:48',40,'2025-08-27 17:51:48','tv_wall','岩板','根据师傅的要求（AB胶、结构胶、云石胶等）','量尺、制作加工一般需要2-3天，网购需要5-7天','自行联系或商家联系','提前确定好样式、颜色'),('2025-08-27 17:52:21',41,'2025-08-27 17:52:21','panel_install','饰面板、各类收口条','根据师傅的要求（结构胶、玻璃胶等）','当地一般有现货，网购需要5-7天','自行联系或商家联系','提前确定好样式、颜色'),('2025-08-27 20:22:19',42,'2025-08-27 20:22:19','kitchen_ceiling','扣板','收口条、丝杆、龙骨等，商家自备、或师傅给出数量','1、当地一般有现货 2、网购需要5-7天，网购需要自行测量面积或让师傅不忙量尺备货','自行联系或商家联系','提前确定好样式、颜色'),('2025-08-27 20:22:55',43,'2025-08-27 20:22:55','putty_second','具体品类、数量清单由油漆师傅给出','无','网上购买一般需要3-5天，当地一般都有现货，不建议网上购买，有问题售后很麻烦','提前联系师傅、沟通好具体施工时间','无'),('2025-08-27 20:23:27',44,'2025-08-27 20:23:27','putty_third','具体品类、数量清单由油漆师傅给出','无','网上购买一般需要3-5天，当地一般都有现货，不建议网上购买，有问题售后很麻烦','提前联系师傅、沟通好具体施工时间','无'),('2025-08-27 20:24:09',45,'2025-08-27 20:24:09','bathroom_fixture','浴室柜、花洒、菜盆水龙头、浴室柜水龙头、马桶、洗衣台水龙头、洗衣机水龙头','角阀、高压管、浴室柜下水、生胶带','3-5天','商家联系或自己提前联系师傅、沟通好具体施工时间','提前确定好样式、颜色等'),('2025-08-27 20:24:42',46,'2025-08-27 20:24:42','wall_polish','无','由师傅给出具体品类、数量，或商家自备','当地有现货','提前联系师傅、沟通好具体施工时间','墙面彻底干后方可打磨'),('2025-08-27 20:25:16',47,'2025-08-27 20:25:16','paint_wallpaper','油漆、墙纸、墙布','由师傅给出具体品类、数量，或商家自备','3-5天','提前联系师傅、沟通好具体施工时间','无'),('2025-08-27 20:25:55',48,'2025-08-27 20:25:55','grille_install','格栅','由师傅给出具体品类、数量，或商家自备','3-5天','提前联系师傅、沟通好具体施工时间','油漆施工完再安格栅'),('2025-08-27 20:26:26',49,'2025-08-27 20:26:26','wood_floor','木地板','由师傅给出具体品类、数量，或商家自备','3-5天','提前联系师傅、沟通好具体施工时间','无'),('2025-08-27 20:26:57',50,'2025-08-27 20:26:57','baseboard_install','踢脚线','由师傅给出具体品类、数量，或商家自备','3-5天','提前联系师傅、沟通好具体施工时间','踢脚线有不同的颜色和材质，需提前确定好材质、样式、颜色等'),('2025-08-27 20:27:26',51,'2025-08-27 20:27:26','cleaning','无','无','无','提前联系师傅、沟通好具体施工时间','把多的垃圾扫一下'),('2025-08-27 20:28:00',52,'2025-08-27 20:28:00','lighting_panel','灯具及开关面板，数量清单由电工给出','数量清单由电工给出','3-5天','提前联系师傅、沟通好具体施工时间','水电完工、试压结束后，电工就需要统计出开关面板数量'),('2025-08-27 20:29:01',53,'2025-08-27 20:29:01','ac_install','空调','由师傅给出具体品类、数量，或商家自备（中央空调、风管机、新风系统风口需要提前联系商家准备）','5-7天','提前联系商家或师傅、沟通好具体施工时间','无'),('2025-08-27 20:29:42',54,'2025-08-27 20:29:42','radiator_install','暖气片','商家自备','5-7天','提前联系商家沟通好具体施工时间','无'),('2025-08-27 20:30:15',55,'2025-08-27 20:30:15','gas_connect','无','无','无','提前联系燃气公司开通天然气','最早开通时间是厨房全部完工，一般是开荒保洁后通天然气'),('2025-08-27 20:30:40',56,'2025-08-27 20:30:40','final_cleaning','无','无','无','提前联系保洁，沟通好具体施工时间','无'),('2025-08-27 20:31:11',57,'2025-08-27 20:31:11','appliance_install','家电（冰箱、电视机、洗衣机、消毒柜等）','商家自备、或工人给出具体的产品及数量','5-7天','提前联系商家或师傅、沟通好具体施工时间','无'),('2025-08-27 20:31:41',58,'2025-08-27 20:31:41','furniture_curtain','家具（沙发、茶几、电视柜、餐桌、床等）、窗帘','商家自备、或工人给出具体的产品及数量','10-15天','提前联系商家或师傅、沟通好具体施工时间','提前选好样式'),('2025-08-27 20:32:32',59,'2025-08-27 20:32:32','smart_system','智能系统、挂画等','商家自备、或工人给出具体的产品及数量','10-15天','提前联系商家或师傅、沟通好具体施工时间','提前选好样式');
/*!40000 ALTER TABLE `sys_project_ready` ENABLE KEYS */;
