--
-- Table structure for table `sys_routes_classify`
--

DROP TABLE IF EXISTS `sys_routes_classify`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_routes_classify` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `createdAt` datetime DEFAULT NULL COMMENT '创建时间',
  `updatedAt` datetime DEFAULT NULL COMMENT '更新时间',
  `name` varchar(20) DEFAULT NULL COMMENT '分类名称',
  `uuid` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'uuid',
  `middleware` varchar(1000) DEFAULT NULL COMMENT '在 Router 里面可以配置多个 Middleware',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注',
  `sort` int DEFAULT '0' COMMENT '越小越靠前',
  `sys` tinyint(1) DEFAULT '0' COMMENT '是否系统',
  PRIMARY KEY (`id`),
